CREATE TABLE Student (StudentNumber TEXT(10) CONSTRAINT PK_Student PRIMARY KEY, FirstName TEXT(50) NOT NULL, LastName TEXT(50) NOT NULL, DateOfBirth DATETIME, ContactInformation TEXT(100), Faculty TEXT(100), ProgrammeOfStudy TEXT(100), AcademicRiskLevel TEXT(6));
CREATE TABLE Administrator (AdminID TEXT(10) CONSTRAINT PK_Admin PRIMARY KEY, FirstName TEXT(50), LastName TEXT(50), ContactInformation TEXT(100), [Role] TEXT(30));
CREATE TABLE Course (CourseCode TEXT(12) CONSTRAINT PK_Course PRIMARY KEY, CourseName TEXT(100), Faculty TEXT(100));
CREATE TABLE Tutor (TutorID TEXT(10) CONSTRAINT PK_Tutor PRIMARY KEY, FirstName TEXT(50) NOT NULL, LastName TEXT(50) NOT NULL, ContactInformation TEXT(100), AcademicAverage DOUBLE, TutoringMode TEXT(10));
CREATE TABLE TutorQualification (TutorID TEXT(10), CourseCode TEXT(12), VerifiedByAdminID TEXT(10), VerificationDate DATETIME, CONSTRAINT PK_Qualification PRIMARY KEY (TutorID, CourseCode), CONSTRAINT FK_QTutor FOREIGN KEY (TutorID) REFERENCES Tutor(TutorID), CONSTRAINT FK_QCourse FOREIGN KEY (CourseCode) REFERENCES Course(CourseCode), CONSTRAINT FK_QAdmin FOREIGN KEY (VerifiedByAdminID) REFERENCES Administrator(AdminID));
CREATE TABLE TutorAvailability (AvailabilityID COUNTER CONSTRAINT PK_Availability PRIMARY KEY, TutorID TEXT(10) NOT NULL, StartAt DATETIME NOT NULL, EndAt DATETIME NOT NULL, CONSTRAINT FK_ATutor FOREIGN KEY (TutorID) REFERENCES Tutor(TutorID));
CREATE TABLE TutoringRequest (RequestID TEXT(12) CONSTRAINT PK_Request PRIMARY KEY, StudentNumber TEXT(10) NOT NULL, CourseCode TEXT(12) NOT NULL, VerifiedByAdminID TEXT(10), MatchedTutorID TEXT(10), SupportType TEXT(40), PriorityLevel TEXT(6), Availability TEXT(255), [Status] TEXT(20), SubmissionDate DATETIME, CONSTRAINT FK_RStudent FOREIGN KEY (StudentNumber) REFERENCES Student(StudentNumber), CONSTRAINT FK_RCourse FOREIGN KEY (CourseCode) REFERENCES Course(CourseCode), CONSTRAINT FK_RAdmin FOREIGN KEY (VerifiedByAdminID) REFERENCES Administrator(AdminID), CONSTRAINT FK_RTutor FOREIGN KEY (MatchedTutorID) REFERENCES Tutor(TutorID));
CREATE TABLE TutoringSession (SessionID TEXT(12) CONSTRAINT PK_Session PRIMARY KEY, RequestID TEXT(12) NOT NULL, StudentNumber TEXT(10) NOT NULL, TutorID TEXT(10) NOT NULL, SessionDate DATETIME, StartTime DATETIME NOT NULL, EndTime DATETIME NOT NULL, [Mode] TEXT(10), AttendanceStatus TEXT(12), TopicsCovered TEXT(255), Feedback DOUBLE, CONSTRAINT FK_SRequest FOREIGN KEY (RequestID) REFERENCES TutoringRequest(RequestID), CONSTRAINT FK_SStudent FOREIGN KEY (StudentNumber) REFERENCES Student(StudentNumber), CONSTRAINT FK_STutor FOREIGN KEY (TutorID) REFERENCES Tutor(TutorID));
CREATE TABLE Report (ReportID TEXT(12) CONSTRAINT PK_Report PRIMARY KEY, AdminID TEXT(10), ReportType TEXT(60), GeneratedDate DATETIME, DateFrom DATETIME, DateTo DATETIME, CONSTRAINT FK_ReportAdmin FOREIGN KEY (AdminID) REFERENCES Administrator(AdminID));
CREATE TABLE StudentAdmin (StudentNumber TEXT(10), AdminID TEXT(10), CONSTRAINT PK_StudentAdmin PRIMARY KEY (StudentNumber, AdminID), CONSTRAINT FK_SAStudent FOREIGN KEY (StudentNumber) REFERENCES Student(StudentNumber), CONSTRAINT FK_SAAdmin FOREIGN KEY (AdminID) REFERENCES Administrator(AdminID));
CREATE TABLE TutorAdmin (TutorID TEXT(10), AdminID TEXT(10), CONSTRAINT PK_TutorAdmin PRIMARY KEY (TutorID, AdminID), CONSTRAINT FK_TATutor FOREIGN KEY (TutorID) REFERENCES Tutor(TutorID), CONSTRAINT FK_TAAdmin FOREIGN KEY (AdminID) REFERENCES Administrator(AdminID));
CREATE INDEX IX_SessionTutor ON TutoringSession(TutorID, StartTime, EndTime);
CREATE INDEX IX_SessionStudent ON TutoringSession(StudentNumber, StartTime, EndTime);

CREATE TABLE AppUser (Username TEXT(50) CONSTRAINT PK_AppUser PRIMARY KEY, PasswordHash TEXT(100), PasswordSalt TEXT(50), UserRole TEXT(15), PersonID TEXT(10), IsActive BIT);
CREATE UNIQUE INDEX UX_TutorContact ON Tutor(ContactInformation);
